export async function updateStaff(token:string,id:string,input:StaffInput,version:number):Promise<StaffMember>{const r=await fetch(`${API}/personnel/${id}`,{method:'PUT',headers:mutationHeaders(token,{'If-Match':String(version)}),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Modification agent impossible'));return r.json();}
