export async function getSchoolingSummary(token:string):Promise<SchoolingSummary>{const r=await fetch(`${API}/schooling/summary`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Synthèse élèves indisponible'));return r.json();}
export type StudentFilters={q?:string;status?:string;class_id?:string;section_id?:string;option_id?:string;gender?:'M'|'F'|'';academic_year_id?:string;all_years?:boolean};
function studentQuery(f:StudentFilters){const qs=new URLSearchParams();for(const k of ['q','status','class_id','section_id','option_id','gender','academic_year_id'] as const){const v=f[k];if(v)qs.set(k,String(v))}if(f.all_years)qs.set('all_years','true');return qs}
export async function listStudents(token:string,params:StudentFilters&{limit?:number;offset?:number}={}):Promise<{items:SchoolingStudent[];limit:number;offset:number;has_more?:boolean}>{const qs=studentQuery(params);qs.set('limit',String(params.limit??200));qs.set('offset',String(params.offset??0));const r=await fetch(`${API}/schooling/students?${qs}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Annuaire élèves indisponible'));return r.json();}
export async function getStudent(token:string,id:string):Promise<SchoolingStudent>{const r=await fetch(`${API}/schooling/students/${id}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Fiche élève indisponible'));return r.json();}
export async function resolveHouseholds(token:string,query:string):Promise<HouseholdCandidate[]>{const qs=new URLSearchParams({q:query});const r=await fetch(`${API}/schooling/families/resolve/candidates?${qs}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Recherche foyer impossible'));return r.json();}
export async function enrollFamily(token:string,input:EnrollmentBatchInput){const r=await fetch(`${API}/schooling/enrollments/family`,{method:'POST',headers:mutationHeaders(token),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Inscription impossible'));return r.json();}
export async function updateStudent(token:string,id:string,version:number,input:Partial<Pick<SchoolingStudent,'last_name'|'middle_name'|'first_name'|'gender'|'birth_date'|'birth_place'|'nationality'|'address'|'previous_school'>>){const r=await fetch(`${API}/schooling/students/${id}`,{method:'PATCH',headers:mutationHeaders(token,{'If-Match':String(version)}),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Modification élève impossible'));return r.json();}
export async function studentLifecycle(token:string,id:string,version:number,eventType:'ABANDON'|'TRANSFER'|'REINTEGRATE'|'SUSPEND',input:{effective_date:string;reason:string;destination?:string|null}){const path=eventType==='ABANDON'?'abandon':eventType==='TRANSFER'?'transfer':eventType==='SUSPEND'?'suspend':'reintegrate';const r=await fetch(`${API}/schooling/students/${id}/${path}`,{method:'POST',headers:mutationHeaders(token,{'If-Match':String(version)}),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Opération scolaire impossible'));return r.json();}
export async function listFamilies(token:string,q='',params:{limit?:number;offset?:number}={}):Promise<{items:SchoolFamily[];limit?:number;offset?:number;has_more?:boolean}>{const qs=new URLSearchParams();if(q)qs.set('q',q);qs.set('limit',String(params.limit??50));qs.set('offset',String(params.offset??0));const r=await fetch(`${API}/schooling/families?${qs}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Répertoire familles indisponible'));return r.json();}
export async function addFamilyGuardian(token:string,familyId:string,input:GuardianInput){const r=await fetch(`${API}/schooling/families/${familyId}/guardians`,{method:'POST',headers:mutationHeaders(token),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Responsable impossible à ajouter'));return r.json();}
