// School articles: price / threshold edit and traced stock movements (administrator finishing pass 2026-10-24).
export async function updateSettingsProduct(token:string,p:SettingsProduct,input:{label:string;currency:'CDF'|'USD';unit_price:string;stock_tracking:boolean;enabled:boolean;low_threshold?:string|null}):Promise<SettingsProduct>{const r=await fetch(`${API}/settings/products/${p.id}`,{method:'PUT',headers:mutationHeaders(token,{'If-Match':String(p.version)}),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Article impossible à modifier'));return r.json()}
export async function moveProductStock(token:string,productId:string,input:{movement_type:'RECEIPT'|'ADJUSTMENT';quantity:string;adjustment_direction?:'INCREASE'|'DECREASE'|null;reason:string;reference?:string|null}):Promise<{quantity:string;low_threshold:string}>{const r=await fetch(`${API}/settings/products/${productId}/stock`,{method:'POST',headers:mutationHeaders(token),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Mouvement de stock refusé'));return r.json()}
export async function putEnrollmentWindow(token:string,yearId:string,input:{enrollment_start:string|null;enrollment_end:string|null}):Promise<{enrollment_start:string|null;enrollment_end:string|null}>{const r=await fetch(`${API}/settings/academic-years/${yearId}/enrollment-window`,{method:'PUT',headers:mutationHeaders(token),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Période d’inscription impossible à enregistrer'));return r.json()}
